queries:
SELECT AVG(avg_ratio) AS mean_of_avg_bytes_per_ms
FROM (
  SELECT m.Name, AVG(CAST(t.Bytes AS REAL) / t.Milliseconds) AS avg_ratio
  FROM Track t
  JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId
  WHERE t.Bytes > 10323804
  GROUP BY m.Name
);
SELECT m.Name, CAST(SUM(t.Bytes) AS REAL) / SUM(t.Milliseconds) AS AvgBytesPerMillisecond
FROM Track t
JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId
GROUP BY m.MediaTypeId, m.Name;
SELECT AVG(Bytes / Milliseconds) FROM Track;
SELECT m.Name, COUNT(*) FROM Track t JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId GROUP BY m.MediaTypeId;
SELECT AVG(avg_ms) FROM (
  SELECT m.MediaTypeId, COALESCE(AVG(t.Milliseconds), 0) AS avg_ms
  FROM MediaType m
  LEFT JOIN Track t ON t.MediaTypeId = m.MediaTypeId AND t.Milliseconds > 300000
  GROUP BY m.MediaTypeId
);
